local a=1000000;local b=1;local function c(d)local e,f=findPlayerStateByUid(d)if f==nil or not f:IsValid()then return false,"대상 플레이어 컨트롤러를 찾지 못했습니다."end;local g=f.Pawn;if g==nil or not g:IsValid()then return false,"대상 플레이어 캐릭터를 찾지 못했습니다."end;local h=g.DamageReactionComponent;if h==nil or not h:IsValid()then return false,"대상 플레이어의 피해 컴포넌트를 찾지 못했습니다."end;h:SlipDamage(a,true,b,true)return true end;return function(i)local j,k,l=xpcall(function()return c(i.playerUid)end,debug.traceback)if not j or not k then local m=j and l or k;i.log("플레이어 즉사 이벤트 실패: "..tostring(i.playerName).." / "..tostring(m))return false,tostring(m)end;local n=i.playerUid;local o=i.playerName;local p,q=pcall(function()ExecuteInGameThreadWithDelay(200,function()local r,s,t=xpcall(function()return c(n)end,debug.traceback)if not r or not s then local m=r and t or s;i.log("즉사 확인 피해 적용 실패: "..tostring(o).." / "..tostring(m))end end)end)if not p then i.log("즉사 확인 피해 예약 실패: "..tostring(o).." / "..tostring(q))end;i.sendSystemToPlayer(i.playerUid,"[후원] 즉사 이벤트가 적용되었습니다.")i.log("플레이어 즉사 이벤트 완료: "..tostring(i.playerName).." / 피해 "..tostring(a))return true,"플레이어 즉사 이벤트를 적용했습니다."end